<script setup>
import { Link, useForm } from '@inertiajs/vue3'; import AdminLayout from '../../../Layouts/AdminLayout.vue';
const props=defineProps({categories:Array,book:Object}); const form=useForm({...props.book, links: props.book.links || []}); const addLink=()=>form.links.push({platform_name:'',url:''}); const submit=()=>form.put(`/admin/books/${props.book.id}`);
</script>
<template><AdminLayout><Link :href="'/admin/books'" class="text-sm text-[#c56b4d]">← বইসমূহ</Link><h1 class="mt-5 font-serif text-4xl">বই সম্পাদনা</h1><form @submit.prevent="submit" class="mt-8 max-w-3xl space-y-6"><div class="grid gap-5 md:grid-cols-2"><label>বাংলা নাম<input v-model="form.title_bn" required class="field" /></label><label>English title<input v-model="form.title_en" required class="field" /></label><label>Slug<input v-model="form.slug" class="field" placeholder="অটো জেনারেট হবে" /></label><label>প্রকাশের বছর<input v-model="form.published_year" type="number" class="field" /></label></div><label>বাংলা বিবরণ<textarea v-model="form.description_bn" required class="field" rows="5" /></label><label>English description<textarea v-model="form.description_en" required class="field" rows="5" /></label><div class="grid gap-5 md:grid-cols-2"><label>ক্যাটাগরি<select v-model="form.category_id" class="field"><option value="">নির্বাচন করুন</option><option v-for="c in categories" :value="c.id">{{ c.name_bn }}</option></select></label><label>স্ট্যাটাস<select v-model="form.status" class="field"><option value="draft">Draft</option><option value="published">Published</option></select></label></div><label class="flex items-center gap-2 text-sm"><input v-model="form.is_featured" type="checkbox" /> হোমপেজে দেখান</label><div><h2 class="font-semibold">কেনার লিংক</h2><div v-for="(link,i) in form.links" :key="i" class="mt-3 grid gap-3 md:grid-cols-2"><input v-model="link.platform_name" placeholder="Rokomari" class="field" /><input v-model="link.url" placeholder="https://..." class="field" /></div><button type="button" @click="addLink" class="mt-3 text-sm text-[#1d6a61]">+ লিংক যোগ করুন</button></div><button :disabled="form.processing" class="rounded-full bg-[#1d4843] px-7 py-3 font-semibold text-white">সংরক্ষণ করুন</button></form></AdminLayout></template>
<style scoped>.field{display:block;margin-top:.5rem;width:100%;border:0;border-radius:.5rem;background:white;padding:.75rem 1rem;box-shadow:inset 0 0 0 1px #dfe1d8;outline:none}.field:focus{box-shadow:inset 0 0 0 2px #c56b4d}label{display:block;font-size:.875rem;color:#49605c}</style>
